import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side','price','qty','seq'}
    seq_counter = 0

    def clean_buy():
        while buy_heap and (buy_heap[0][2] not in book or book[buy_heap[0][2]]['qty'] <= 0):
            heapq.heappop(buy_heap)

    def clean_sell():
        while sell_heap and (sell_heap[0][2] not in book or book[sell_heap[0][2]]['qty'] <= 0):
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['qty'] = 0
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                if top_id not in book or book[top_id]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and price is not None and top_price > price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, top_id, resting['price'], trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    del book[top_id]
                    heapq.heappop(sell_heap)
                clean_sell()
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq_counter}
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if top_id not in book or book[top_id]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and price is not None and top_price < price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([top_id, oid, resting['price'], trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] <= 0:
                    del book[top_id]
                    heapq.heappop(buy_heap)
                clean_buy()
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq_counter}
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

